#!/usr/bin/env python3
"""Build readable absolute-metric slices from portfolio-report.py exports."""
import csv
from pathlib import Path
HERE=Path(__file__).resolve().parent
OUT=HERE/'evidence/portfolio'
rows={n:list(csv.DictReader((OUT/(n+'.csv')).open())) for n in ['reads','tiny','mutation','edits','packets','cold']}
def find(panel, **keys):
    hits=[r for r in rows[panel] if all(r.get(k)==str(v) for k,v in keys.items())]
    assert len(hits)==1,(panel,keys,len(hits))
    return hits[0]
def ns(panel,field,**keys):return float(find(panel,**keys)[field+'_median'])
def pair(panel,field,concurrency='concurrency',**keys):
    return ' / '.join(f'{ns(panel,field,**keys,**{concurrency:c}):.2f}' for c in [1,8])
def table(lines,head,body):
    lines+=['| '+' | '.join(head)+' |','| '+' | '.join(['---']*len(head))+' |']
    lines+=['| '+' | '.join(map(str,r))+' |' for r in body];lines+=['']
profiles=[('zen5','avx2'),('zen5','avx512'),('granite','avx2'),('granite','avx512'),('neon','neon')]
lines=['# Absolute portfolio scorecard','','Generated by `portfolio-scorecard.py`; all cells, ranges and sample counts are in the adjacent CSVs.','C1 / C8 means dependent request latency / reciprocal throughput with eight independent chains, ns/request.','Construction and packing instead report whole-block work normalized per rank; their C8 is an eight-block batch, not per-slot latency.','The raw cohorts and their limits are described in [the qualification report](../../PORTFOLIO.md).','', '## Warm complete value and inverse consumers','','256 ranks, one block, M4095/B1048320, grouped U present. Each lookup consumes a payload word that determines the next request.','']
body=[]
for platform,isa in profiles:
    for encoding,label in [(0,'Absolute Ends'),(1,'Sizes'),(2,'Relative Ends')]:
        k=dict(platform=platform,isa=isa,encoding=encoding,maximum=4095,count=256,nodes=1,used=1,placement=0,method='streampack')
        old='—' if encoding==2 else pair('reads','ns_request',variant='before',operation='value_chain',**k)
        body.append([platform+'/'+isa,label,old,pair('reads','ns_request',variant='after',operation='value_chain',**k),pair('reads','ns_request',variant='after',operation='reverse_value_chain',**k),pair('reads','ns_request',variant='after',operation='value_chain',**(k|{'method':'independent_fused'}))])
table(lines,['CPU / ISA','Codec','Frozen value C1 / C8','Current value C1 / C8','Current reverse+value C1 / C8','Fused value C1 / C8'],body)
lines+=['## Full-capacity bytes','','Packed metadata includes D, directory, local fields/U and control; excludes payload, allocation padding and native prepared objects. Bounds are fixed while occupancy grows.','']
body=[]
for maximum,limit in [(15,3840),(16,4096),(255,65280),(4095,1048320),(4096,1048576),(65535,65535)]:
    body.append([maximum,limit]+[int(float(find('reads',platform='neon',isa='neon',variant='after',encoding=e,maximum=maximum,count=256,nodes=1,used=u,placement=0,method='streampack',operation='value_chain',concurrency=1)['encoded_bytes_median'])) for e,u in [(0,0),(1,0),(2,0),(0,1),(1,1),(2,1)]])
table(lines,['M','B','Abs no U','Sizes no U','Relative no U','Abs + U','Sizes + U','Relative + U'],body)
lines+=['## Writes and complete transfer','','M4095/B1048320, 256 ranks, grouped U. Values are copied, slack cleared and actual geometry/controls stored. Restore and whole-output verification are untimed. Columns are ns/rank of complete block work; CSV also has ns/block.','']
body=[]
for platform,isa in profiles:
    for encoding,label in [(0,'Absolute Ends'),(1,'Sizes'),(2,'Relative Ends')]:
        k=dict(platform=platform,isa=isa,encoding=encoding,maximum=4095,used=1,placement=0)
        old='—' if encoding==2 else pair('mutation','ns_rank',variant='before',method='per_slot',operation='construct',**k)
        body.append([platform+'/'+isa,label,old,pair('mutation','ns_rank',variant='after',method='per_slot',operation='construct',**k),pair('mutation','ns_rank',variant='after',method='carried_encoder',operation='construct',**k),pair('mutation','ns_rank',variant='after',method='independent_fused',operation='construct',**k),pair('mutation','ns_rank',variant='after',method='per_slot',operation='soft_pack',**k),pair('mutation','ns_rank',variant='after',method='per_slot',operation='shuffled_transfer',**k)])
table(lines,['CPU / ISA','Codec','Frozen append','Current append','Carried construction','Fused construction','Packing','Checked shuffled transfer'],body)
lines+=['## Numeric edit pairs','','M4095, actual +1 then -1 with source-qualified damage and an observability boundary after each mutation. ns/pair; C1 / C8 independent chains. Boundary movement and suffix resize are distinct semantics.','']
body=[]
for platform,isa in profiles:
    for e,label in [(0,'Absolute Ends'),(1,'Sizes'),(2,'Relative Ends')]:
        k=dict(platform=platform,isa=isa,variant='after',encoding=e,maximum=4095)
        body.append([platform+'/'+isa,label]+[pair('edits','ns_pair',method=m,operation=op,**k) for op,m in [('boundary_pair','shared'),('boundary_pair','independent_packed'),('resize_pair','shared'),('resize_pair','independent_packed')]])
table(lines,['CPU / ISA','Codec','Shared boundary','Fused boundary','Shared resize','Fused resize'],body)
lines+=['## Native packet composition','','M4095, R32/U16, grouped. Complete native read16/reduction/payload-word consumer. One/eight independent dependent chains; ns/group. Direct vs actual Ikea scoped CPS, not an independently fused packet baseline.','']
body=[]
for platform,isa in profiles:
    for layout in ['absolute_ends','sizes','relative_ends']:
        k=dict(platform=platform,isa=isa,variant='after',layout=layout,maximum=4095,nodes=1,used=1,placement=0)
        body.append([platform+'/'+isa,layout,pair('packets','ns',concurrency='chains',consumer='direct_native',**k),pair('packets','ns',concurrency='chains',consumer='native_chain',**k)])
table(lines,['CPU / ISA','Codec','Direct C1 / C8','CPS C1 / C8'],body)
lines+=['## Large-population actual Loom consumers','','524288 blocks, mixed assigned counts, point plus selected child; 262147 requests per repetition. Nominal allocation is not a DRAM-residence claim. Same concurrency comparisons are shown alongside C1. ns/request; frame/scheduler and setup/drain remain in cold.csv.','']
body=[]
for platform,isa in profiles:
    for impl,label in [('production_width_phase','Curated Sizes'),('relative_end_phase','Generic Relative Ends')]:
        # Name is kept exactly as the driver writes it.
        if not any(r['implementation']==impl for r in rows['cold']):continue
        k=dict(platform=platform,isa=isa,variant='after',nodes=524288,mixed=1,span=257,metric='point_child',implementation=impl)
        body.append([platform+'/'+isa,label]+[f'{ns("cold","ns",execution=x,width=c,**k):.2f}' for x,c in [('direct',1),('direct',32),('manual_hints',32),('loom_hints',32),('loom_no_hints',32)]])
table(lines,['CPU / ISA','Path','C1 latency','Direct C32','Manual C32 + hints','Ring C32 + hints','Ring C32 no hints'],body)
lines+=['## Known counterexamples','','NEON tight extent M65535/B65535, 64-block footprint, no U: Sizes typed reverse+value C8 is '+f'{ns("reads","ns_request",platform="neon",isa="neon",variant="before",encoding=1,maximum=65535,count=256,nodes=64,used=0,placement=0,method="streampack",operation="reverse_value_chain",concurrency=8):.2f}'+' ns frozen vs '+f'{ns("reads","ns_request",platform="neon",isa="neon",variant="after",encoding=1,maximum=65535,count=256,nodes=64,used=0,placement=0,method="streampack",operation="reverse_value_chain",concurrency=8):.2f}'+' ns current. Relative Ends is not a universal inverse-throughput winner on NEON. The complete cells are retained.','','Initial cursor construction regressions are preserved in `cursor-diagnostic.csv`; final writes above come from a separate source-qualified replay after removing self-referential effect state. No old/new timing samples were pooled.','']
(OUT/'scorecard.md').write_text('\n'.join(lines))
print(OUT/'scorecard.md')
